INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Effektivspannung dasselbe wie die Scheitelspannung?', 2, '[{"text": "Nein", "correct": true, "because": "Effektivwert vs. Maximalwert"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Werte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat die Effektivspannung?', 3, '[{"text": "Leistung einer Wechselspannung messen", "correct": true, "because": "Effektiver Wert"}, {"text": "Maximale Spannung anzeigen", "correct": false, "because": "Scheitelwert"}, {"text": "Frequenz bestimmen", "correct": false, "because": "Andere Größe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat die Effektivspannung?', 5, '[{"text": "RMS-Wert", "correct": true, "because": "Root Mean Square"}, {"text": "Wechselspannung", "correct": true, "because": "Sinusförmig"}, {"text": "Gleichspannung", "correct": false, "because": "Nicht konstant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Effektivspannung ist kleiner als die Scheitelspannung. b) Sie gilt nur für Gleichspannung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wechselspannung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Effektivspannung?', 4, '[{"text": "Frequenz", "correct": false, "because": "Beeinflusst Messung"}, {"text": "Scheitelwert", "correct": false, "because": "Grundlage für Berechnung"}, {"text": "Kabelgewicht", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Effektivspannung bei 230 V AC etwa 325 V beträgt?', 2, '[{"text": "Nein", "correct": true, "because": "325 V ist Scheitelwert"}, {"text": "Ja", "correct": false, "because": "230 V ist Effektivwert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie berechnet sich die Effektivspannung einer Sinusspannung?', 3, '[{"text": "Scheitelspannung durch √2", "correct": true, "because": "U_eff = U_s / √2"}, {"text": "Scheitelspannung mal 2", "correct": false, "because": "Falsche Formel"}, {"text": "Frequenz mal Spannung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Kenntnis der Effektivspannung?', 5, '[{"text": "Leistungsberechnung", "correct": true, "because": "Effektiver Wert"}, {"text": "Vergleich mit Gleichspannung", "correct": true, "because": "Gleiche Wirkung"}, {"text": "Maximale Frequenz", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Die Effektivspannung ist der RMS-Wert. b) Sie ist immer gleich der Scheitelspannung. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Scheitelwert höher"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um die Effektivspannung zu berechnen?', 4, '[{"text": "Scheitelspannung", "correct": false, "because": "Grundlage"}, {"text": "Wurzel 2", "correct": false, "because": "Formelkonstante"}, {"text": "Kabeldicke", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Effektivspannung bei Gleichspannung relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Wechselspannung"}, {"text": "Ja", "correct": false, "because": "Konstant bei DC"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte nutzen die Effektivspannung?', 4, '[{"text": "Netzteile", "correct": true, "because": "Wechselspannung umwandeln"}, {"text": "Monitore", "correct": true, "because": "Stromversorgung"}, {"text": "USB-Sticks", "correct": false, "because": "Gleichspannung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Effektivspannung nur für Sinusspannung gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch andere Formen"}, {"text": "Ja", "correct": false, "because": "Allgemein anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Effektivspannung?', 3, '[{"text": "Leistungsberechnung", "correct": true, "because": "Effektiver Wert"}, {"text": "Kabeldesign", "correct": false, "because": "Sekundär"}, {"text": "Spannungsfarbe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Effektivspannung ist etwa 0,707 der Scheitelspannung. b) Sie ist nur für Hochspannung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Allgemein anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werte beeinflussen die Effektivspannung?', 5, '[{"text": "Scheitelspannung", "correct": true, "because": "Basis der Berechnung"}, {"text": "Frequenz", "correct": true, "because": "Wellenform"}, {"text": "Kabellänge", "correct": false, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Effektivspannung unwichtig?', 3, '[{"text": "Wellenform", "correct": false, "because": "Beeinflusst Wert"}, {"text": "Scheitelwert", "correct": false, "because": "Grundlage"}, {"text": "Papiergröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Effektivspannung bei 230 V AC immer gleich?', 3, '[{"text": "Ja", "correct": true, "because": "Standardwert in Europa"}, {"text": "Nein", "correct": false, "because": "Konstant bei 230 V"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Effektivspannung bei Gleichspannung gleich der Spannung ist?', 2, '[{"text": "Ja", "correct": true, "because": "Kein Unterschied"}, {"text": "Nein", "correct": false, "because": "Gleich bei DC"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für die Effektivspannung zentral?', 4, '[{"text": "RMS-Berechnung", "correct": true, "because": "Effektiver Wert"}, {"text": "Maximale Amplitude", "correct": false, "because": "Scheitelwert"}, {"text": "Physische Kabel", "correct": false, "because": "Kein direkter Bezug"}]');
